with flattened_attrs as (select id, coupon_codes, attributes, exists(items, li -> li.price > 100) as has_premium_item, array_max(transform(items, li -> li.price)) as max_item_price, attributes['device'] as device from carts where size(coupon_codes) > 2) select case when max_item_price >= 235 then 'PREMIUM' else 'STANDARD' end as max_item_price_tier, max(max_item_price) as max_max_item_price, count(*) as event_count, count(*) as event_count_2, count(*) as num_rows from flattened_attrs group by case when max_item_price >= 235 then 'PREMIUM' else 'STANDARD' end having count(*) > 1 order by event_count_2
